using System.Collections.Generic;public class Solution{public bool ValidTree(int n,int[][]e){if(e.Length!=n-1)return false;var g=new List<int>[n];for(int i=0;i<n;i++)g[i]=new();foreach(var x in e){g[x[0]].Add(x[1]);g[x[1]].Add(x[0]);}var v=new bool[n];var st=new Stack<int>();st.Push(0);while(st.Count>0){int u=st.Pop();if(v[u])continue;v[u]=true;foreach(int x in g[u])if(!v[x])st.Push(x);}foreach(bool x in v)if(!x)return false;return true;}}
